namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CourseCode { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public int DepartmentId { get; set; }
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and software systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS 101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented basics.", Credits = 3, Schedule = "MWF 10:00-10:50 AM", DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures", CourseCode = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and hash tables.", Credits = 4, Schedule = "TTh 1:00-2:15 PM", DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education.", IsFeatured = false },
            new() { Id = 3, Title = "Web Development", CourseCode = "CS 330", Description = "Modern web application development with ASP.NET Core, Blazor, and cloud deployment.", Credits = 3, Schedule = "MWF 2:00-2:50 PM", DepartmentId = 1, InstructorName = "Prof. Brian Moss", InstructorBio = "Prof. Moss spent a decade in industry building large-scale web applications before joining academia.", IsFeatured = true },
            new() { Id = 4, Title = "Algorithms", CourseCode = "CS 401", Description = "Design and analysis of algorithms. Topics include sorting, searching, dynamic programming, and graph algorithms.", Credits = 4, Schedule = "TTh 9:30-10:45 AM", DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education.", IsFeatured = false },

            // Mathematics
            new() { Id = 5, Title = "Calculus I", CourseCode = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "MWF 9:00-9:50 AM", DepartmentId = 2, InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim is a renowned mathematician specializing in applied analysis and mathematical modeling.", IsFeatured = true },
            new() { Id = 6, Title = "Linear Algebra", CourseCode = "MATH 220", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 11:00 AM-12:15 PM", DepartmentId = 2, InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim is a renowned mathematician specializing in applied analysis and mathematical modeling.", IsFeatured = false },
            new() { Id = 7, Title = "Discrete Mathematics", CourseCode = "MATH 250", Description = "Logic, sets, combinatorics, graph theory, and proof techniques.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", DepartmentId = 2, InstructorName = "Prof. David Rowe", InstructorBio = "Prof. Rowe has published extensively on combinatorics and theoretical computer science.", IsFeatured = false },

            // English
            new() { Id = 8, Title = "English Composition", CourseCode = "ENG 101", Description = "Develop critical reading and writing skills through analysis of diverse texts.", Credits = 3, Schedule = "MWF 1:00-1:50 PM", DepartmentId = 3, InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez is an award-winning author and writing instructor with 20 years of teaching experience.", IsFeatured = false },
            new() { Id = 9, Title = "American Literature", CourseCode = "ENG 230", Description = "Survey of American literature from the colonial period to the present.", Credits = 3, Schedule = "TTh 2:30-3:45 PM", DepartmentId = 3, InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez is an award-winning author and writing instructor with 20 years of teaching experience.", IsFeatured = false },
            new() { Id = 10, Title = "Creative Writing", CourseCode = "ENG 310", Description = "Workshop-based course in fiction and poetry writing with peer critique.", Credits = 3, Schedule = "TTh 4:00-5:15 PM", DepartmentId = 3, InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright is a published novelist and poet who brings real-world creative experience to the classroom.", IsFeatured = true },

            // Physics
            new() { Id = 11, Title = "General Physics I", CourseCode = "PHYS 201", Description = "Mechanics, thermodynamics, and waves with calculus-based problem solving.", Credits = 4, Schedule = "MWF 8:00-8:50 AM", DepartmentId = 4, InstructorName = "Dr. Robert Tanaka", InstructorBio = "Dr. Tanaka is a former NASA researcher specializing in astrophysics and mechanics.", IsFeatured = false },
            new() { Id = 12, Title = "Electricity and Magnetism", CourseCode = "PHYS 202", Description = "Electric fields, circuits, magnetic fields, and electromagnetic waves.", Credits = 4, Schedule = "MWF 10:00-10:50 AM", DepartmentId = 4, InstructorName = "Dr. Robert Tanaka", InstructorBio = "Dr. Tanaka is a former NASA researcher specializing in astrophysics and mechanics.", IsFeatured = false },
            new() { Id = 13, Title = "Modern Physics", CourseCode = "PHYS 310", Description = "Special relativity, quantum mechanics, and atomic physics.", Credits = 3, Schedule = "TTh 10:00-11:15 AM", DepartmentId = 4, InstructorName = "Dr. Elena Petrov", InstructorBio = "Dr. Petrov conducts research in quantum computing and has published over 50 papers in the field.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) => true;
}

