@page "/courses"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Courses</PageTitle>

<h1>Course Catalog</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses..."
               @bind="searchText" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

<table class="table table-striped">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Credits</th>
            <th>Department</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in FilteredCourses)
        {
            <tr>
                <td>@course.CourseCode</td>
                <td>@course.Title</td>
                <td>@course.Credits</td>
                <td>@(departments.FirstOrDefault(d => d.Id == course.DepartmentId)?.Name)</td>
                <td><a href="@($"course/{course.Id}")" class="btn btn-sm btn-outline-primary">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@if (!FilteredCourses.Any())
{
    <p class="text-muted">No courses match your search criteria.</p>
}

@code {
    private List<UniversityCourseCatalog.Models.Department> departments = new();
    private List<UniversityCourseCatalog.Models.Course> allCourses = new();
    private string searchText = "";
    private int selectedDepartmentId;

    private IEnumerable<UniversityCourseCatalog.Models.Course> FilteredCourses =>
        CatalogService.GetCourses(
            string.IsNullOrWhiteSpace(searchText) ? null : searchText,
            selectedDepartmentId > 0 ? selectedDepartmentId : null);

    protected override Task OnInitializedAsync()
    {
        departments = CatalogService.GetDepartments();
        allCourses = CatalogService.GetCourses(null, null);
        return Task.CompletedTask;
    }
}

@page "/course/{Id:int}"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <h1>Course not found</h1>
    <p>The requested course does not exist.</p>
    <a href="courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    <h1>@course.Title</h1>
    <span class="badge bg-secondary fs-6 mb-3">@course.CourseCode</span>

    <div class="row mt-3">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4>Details</h4>
            <dl class="row">
                <dt class="col-sm-3">Credits</dt>
                <dd class="col-sm-9">@course.Credits</dd>

                <dt class="col-sm-3">Schedule</dt>
                <dd class="col-sm-9">@course.Schedule</dd>
            </dl>

            <h4>Instructor</h4>
            <p><strong>@course.InstructorName</strong></p>
            <p>@course.InstructorBio</p>
        </div>
    </div>

    <div class="mt-3">
        <a href="courses" class="btn btn-outline-secondary me-2">Back to Courses</a>
        <a href="@($"enroll?courseId={course.Id}")" class="btn btn-primary">Enroll in this Course</a>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enroll</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, your enrollment request has been received.</p>
    </div>
    <a href="courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <EditForm Model="Model" FormName="enrollment" OnValidSubmit="HandleSubmit" method="post">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.CourseCode - @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<UniversityCourseCatalog.Models.Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses(null, null);
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        submitted = true;
    }
}

